// Fixed access unit containing two GA94 caption SEI NALUs. The first SEI
// NALU also carries an unregistered user data SEI message and an emulation
// prevention byte. Fixtures were generated by a standalone script and are
// pinned byte-by-byte.
var fxMainAu = [][]byte{
	{0x09, 0xf0},
	{0x41, 0x9a, 0x12, 0x34},
	{
		0x06, 0x04, 0x11, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x42,
		0x00, 0x9f, 0x14, 0x80, 0xdf, 0x00, 0x00, 0xff, 0x05, 0x05, 0xaa, 0x00,
		0x00, 0x03, 0x01, 0xdd, 0x80,
	},
	{
		0x06, 0x04, 0x14, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x43,
		0x00, 0xbf, 0x01, 0x80, 0xff, 0x25, 0x01, 0x1f, 0x00, 0x00, 0xff, 0x80,
	},
}

var fxShortT35 = []byte{0x06, 0x04, 0x01, 0xb5, 0x80}

var fxWrongCountry = []byte{
	0x06, 0x04, 0x0b, 0x26, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x40, 0x00, 0xff, 0x80,
}

var fxWrongProvider = []byte{
	0x06, 0x04, 0x0b, 0xb5, 0x00, 0x3b, 0x47, 0x41, 0x39, 0x34, 0x03, 0x40, 0x00, 0xff, 0x80,
}

var fxWrongIdentifier = []byte{
	0x06, 0x04, 0x0b, 0xb5, 0x00, 0x31, 0x44, 0x54, 0x47, 0x31, 0x06, 0x00, 0x00, 0x03, 0x00, 0x80,
}

var fxOversizeCcCount = []byte{
	0x06, 0x04, 0x0b, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x5f, 0x00, 0xff, 0x80,
}

var fxTruncatedGA94 = []byte{
	0x06, 0x04, 0x09, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x41, 0x80,
}

// cc_count = 1 with the cc_data block and marker missing, so the payload is
// shorter than the declared structure.
var fxTruncatedCCData = []byte{
	0x06, 0x04, 0x0c, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x41,
	0x00, 0x9f, 0x14, 0x80,
}

var fxProcessFlagZero = []byte{
	0x06, 0x04, 0x0e, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x01, 0x00,
	0x9f, 0x14, 0x80, 0xff, 0x80,
}

var fxCcCountZero = []byte{
	0x06, 0x04, 0x0b, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x00, 0x00, 0xff, 0x80,
}

var fxWrongUserDataType = []byte{
	0x06, 0x04, 0x0b, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x07, 0x40, 0x00, 0xff, 0x80,
}

var fxBadMarker = []byte{
	0x06, 0x04, 0x0e, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x41, 0x00,
	0x9f, 0x14, 0x80, 0x00, 0x80,
}

var fxOtherSEINALU = []byte{
	0x06, 0x05, 0x05, 0xaa, 0x00, 0x00, 0x03, 0x01, 0xdd, 0x80,
}

var fxNoCaptionAU = [][]byte{
	{0x09, 0xf0},
	{0x41, 0x9a, 0x12, 0x34},
	fxOtherSEINALU,
}

var fxEmptySEINALU = []byte{0x06}

var fxTruncatedSEINALU = []byte{0x06, 0x04, 0xff}

// GA94 SEI containing an emulation prevention byte (00 00 03 01) inside the
// cc_data region. After removal the two blocks must be restored.
var fxEPBInsideT35 = []byte{
	0x06, 0x04, 0x11, 0xb5, 0x00, 0x31, 0x47, 0x41, 0x39, 0x34, 0x03, 0x42,
	0x00, 0x9f, 0x00, 0x00, 0x03, 0x01, 0x00, 0x00, 0xff, 0x80,
}

func TestExtractCCData(t *testing.T) {
	// snapshot the AU before extraction to prove NALUs are not modified
	auCopy := make([][]byte, len(fxMainAu))
	for i, nalu := range fxMainAu {
		auCopy[i] = append([]byte(nil), nalu...)
	}

	const pts int64 = 123456789

	groups, err := h264.ExtractCCData(fxMainAu, pts)
	require.NoError(t, err)

	// two groups, one per GA94 SEI NALU, in original order
	require.Equal(t, []h264.CCDataGroup{
		{
			PTS: pts,
			CCData: []h264.CCData{
				{CCValid: true, CCType: 0, Data: [2]byte{0x14, 0x80}}, // CEA-608 field 1
				{CCValid: true, CCType: 2, Data: [2]byte{0x00, 0x00}}, // CEA-708 packet
			},
		},
		{
			PTS: pts,
			CCData: []h264.CCData{
				{CCValid: true, CCType: 1, Data: [2]byte{0x01, 0x80}},  // CEA-608 field 2
				{CCValid: true, CCType: 3, Data: [2]byte{0x25, 0x01}},  // CEA-708 packet start
				{CCValid: false, CCType: 0, Data: [2]byte{0x00, 0x00}}, // invalid block kept
			},
		},
	}, groups)

	// all cc_data bytes match the pinned payload bytes in order
	var flat []byte
	for _, group := range groups {
		for _, cc := range group.CCData {
			flat = append(flat, cc.Data[:]...)
		}
	}
	require.Equal(t, []byte{
		0x14, 0x80, 0x00, 0x00,
		0x01, 0x80, 0x25, 0x01, 0x00, 0x00,
	}, flat)

	require.Equal(t, auCopy, fxMainAu)
}

// emulation prevention inside the T.35 payload is removed before parsing, so
// both cc_data blocks are recovered with their original bytes.
func TestExtractCCDataEmulationPrevention(t *testing.T) {
	groups, err := h264.ExtractCCData([][]byte{fxEPBInsideT35}, 7)
	require.NoError(t, err)
	require.Equal(t, []h264.CCDataGroup{
		{
			PTS: 7,
			CCData: []h264.CCData{
				{CCValid: true, CCType: 0, Data: [2]byte{0x00, 0x00}},
				{CCValid: false, CCType: 0, Data: [2]byte{0x00, 0x00}},
			},
		},
	}, groups)
}

func TestExtractCCDataErrorsAndEdgeCases(t *testing.T) {
	for _, ca := range []struct {
		name string
		au   [][]byte
		err  string
	}{
		{
			name: "short t35 payload",
			au:   [][]byte{fxShortT35},
			err:  "T.35 payload is too short",
		},
		{
			name: "oversize cc_count",
			au:   [][]byte{fxOversizeCcCount},
			err:  "GA94 payload is too short for cc_count = 31",
		},
		{
			name: "truncated ga94 payload",
			au:   [][]byte{fxTruncatedGA94},
			err:  "GA94 payload is too short for cc_count = 1",
		},
		{
			name: "truncated cc_data block",
			au:   [][]byte{fxTruncatedCCData},
			err:  "GA94 payload is too short for cc_count = 1",
		},
		{
			name: "bad marker bits",
			au:   [][]byte{fxBadMarker},
			err:  "GA94 marker_bits must be 0xff, got 0x00",
		},
		{
			name: "truncated sei message",
			au:   [][]byte{fxTruncatedSEINALU},
			err:  "truncated SEI payload size",
		},
		{
			name: "empty sei nalu",
			au:   [][]byte{fxEmptySEINALU},
			err:  "SEI NALU is too short",
		},
	} {
		t.Run(ca.name, func(t *testing.T) {
			groups, err := h264.ExtractCCData(ca.au, 1000)
			require.EqualError(t, err, ca.err)
			require.Nil(t, groups)
		})
	}
}

func TestExtractCCDataIgnored(t *testing.T) {
	for _, ca := range []struct {
		name string
		au   [][]byte
	}{
		{"wrong country", [][]byte{fxWrongCountry}},
		{"wrong provider", [][]byte{fxWrongProvider}},
		{"wrong user identifier", [][]byte{fxWrongIdentifier}},
		{"process flag zero", [][]byte{fxProcessFlagZero}},
		{"cc count zero", [][]byte{fxCcCountZero}},
		{"non-cc user data type", [][]byte{fxWrongUserDataType}},
		{"other sei only", [][]byte{fxOtherSEINALU}},
		{"au without captions", fxNoCaptionAU},
		{"empty au", [][]byte{}},
		{"non-sei nalus only", [][]byte{{0x09, 0xf0}, {0x41, 0x9a, 0x12, 0x34}}},
	} {
		t.Run(ca.name, func(t *testing.T) {
			groups, err := h264.ExtractCCData(ca.au, 1000)
			require.NoError(t, err)
			require.Empty(t, groups)
		})
	}
}

// non-caption user data must remain parseable and NALUs must stay untouched:
// an AU mixing a GA94 SEI, an unregistered SEI and video NALUs goes through
// an Annex-B round trip unchanged, while captions are still extracted.
func TestExtractCCDataPreservesOtherSEI(t *testing.T) {
	au := fxNoCaptionAU
	au = append(au, fxMainAu[2]) // add a GA94 SEI NALU

	before, err := h264.AnnexB(au).Marshal()
	require.NoError(t, err)

	groups, err := h264.ExtractCCData(au, 42)
	require.NoError(t, err)
	require.Equal(t, []h264.CCDataGroup{
		{
			PTS: 42,
			CCData: []h264.CCData{
				{CCValid: true, CCType: 0, Data: [2]byte{0x14, 0x80}},
				{CCValid: true, CCType: 2, Data: [2]byte{0x00, 0x00}},
			},
		},
	}, groups)

	var decoded h264.AnnexB
	require.NoError(t, decoded.Unmarshal(before))
	after, err := decoded.Marshal()
	require.NoError(t, err)
	require.Equal(t, before, after)
}

func FuzzExtractCCData(f *testing.F) {
	for _, nalu := range fxMainAu {
		f.Add(nalu)
	}
	f.Add(fxOversizeCcCount)
	f.Add(fxTruncatedGA94)
	f.Add(fxBadMarker)
	f.Add(fxEmptySEINALU)

	f.Fuzz(func(_ *testing.T, nalu []byte) {
		_, _ = h264.ExtractCCData([][]byte{nalu}, 1) //nolint:errcheck
	})
}
